//     modelo,
//     kit,
//     descripcion,
//     precio_total_sin_iva,
//     precio_total_con_iva,
//     valor_cheque_total
//   }

const raw = $input.first().json;

// ────────────────────────────────────────────────────────────────
// HELPERS
// ────────────────────────────────────────────────────────────────
function safeJsonParse(value, fallback) {
  if (value === null || value === undefined || value === '') return fallback;
  if (typeof value === 'object') return value;
  try {
    return JSON.parse(value);
  } catch (e) {
    return fallback;
  }
}

function formatFecha(iso) {
  if (!iso) return '-';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return iso;
  return d.toLocaleDateString('es-AR', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
  });
}

function formatUSD(num) {
  if (num === null || num === undefined || num === '' || Number.isNaN(Number(num))) {
    return '-';
  }

  return 'US$ ' + Number(num).toLocaleString('es-AR', {
    minimumFractionDigits: 0,
    maximumFractionDigits: 2,
  });
}

// Convierte "USD 55.448.-" a "US$ 55.448"
function normalizeUsdString(value) {
  if (!value) return '-';

  const num = parseUsdString(value);
  if (num === null) return String(value);

  return formatUSD(num);
}

function parseUsdString(value) {
  if (value === null || value === undefined || value === '') return null;
  if (typeof value === 'number') return value;

  let str = String(value).trim();

  str = str
    .replace(/USD/gi, '')
    .replace(/US\$/gi, '')
    .replace(/\.\-/g, '')
    .replace(/\s+/g, '')
    .trim();

  if (str.includes(',') && str.includes('.')) {
    str = str.replace(/\./g, '').replace(',', '.');
  } else if (str.includes(',')) {
    str = str.replace(',', '.');
  } else {
    const dotCount = (str.match(/\./g) || []).length;
    if (dotCount >= 1) {
      str = str.replace(/\./g, '');
    }
  }

  const n = Number(str);
  return Number.isNaN(n) ? null : n;
}

