function getItemsKit(modelo, kit, descripcionKit) {
  const items = KIT_ITEMS[modelo]?.[kit];

  if (!items) {
    return `<li class="kit-item"><span class="icon">▶</span>${descripcionKit || ''}</li>`;
  }

  return items.map(item => {
    if (item.aplica) {
      return `<li class="kit-item"><span class="icon">▶</span>${item.texto}</li>`;
    }
    return `<li class="kit-item no-aplica"><span class="icon">✗</span>${item.texto} <strong>(NO APLICA)</strong></li>`;
  }).join('\n');
}

// ────────────────────────────────────────────────────────────────
// COMPLEMENTOS HTML
// ────────────────────────────────────────────────────────────────
function normalizeComplementoLabel(value) {
  if (!value) return '-';

  const s = String(value).trim().toLowerCase();

  if (s === 'antena rtk 2') return 'Antena RTK 2';
  if (s === 'dji relay') return 'DJI Relay';
  if (s === 'mezclador 600l') return 'Mezclador 600L';
  if (s === 'mezclador 320l') return 'Mezclador 320L';

  return String(value);
}

function getComplementosHtml(complementosList) {
  if (!Array.isArray(complementosList) || complementosList.length === 0) return '';

  const items = complementosList.map(c => {
    const descripcion = normalizeComplementoLabel(c);
    return `<div class="complemento-item"><span class="icon">▶</span>${descripcion}</div>`;
  }).join('\n');

  return `
    <div class="complementos-section">
      <strong style="font-size:10px;text-transform:uppercase;">Complementos:</strong>
      ${items}
    </div>
  `;
}

// ────────────────────────────────────────────────────────────────
